var login = () => {
    var username = source.getLoginInfoMap().get("账号");
    var password = source.getLoginInfoMap().get("密码");
    var res = java.post(
        "https://example.com/api/v1/auth/login",
        JSON.stringify({
            username: username,
            password: password,
            app: "legado"
        }),
        {"Content-Type": "application/json"}
    );
    source.putLoginHeader(JSON.stringify({
        Authorization: `Bearer ${res.body()}`
    }));
}
login();

